/*
 * TO ADD A NEW CORE MIGRATION: run `pnpm migrate generate "add fancy new field"` and fill in
 * up()/down(). Registration is automatic: core.generated.ts (gitignored) imports every migration
 * file in this directory and is regenerated by apps/client/scripts/generate-premium-glue.mjs
 * (`pnpm codegen`, also run on install, dev and build).
 *
 * Premium overlays contribute migrations separately via b4mContributions.migrationsExport -
 * see premium.generated.ts (gitignored, generated by the same script). Do not add overlay
 * migrations here.
 */

// premium.generated.ts is regenerated from every premium overlay's b4mContributions.migrationsExport
// (empty array when no overlay declares one - see that script's generateMigrations for the
// present/absent forms).
import { coreMigrations } from './core.generated';
import { premiumMigrations } from './premium.generated';

// Single source of truth - see MigrationModel.ts for why this lives in @bike4mind/database
// rather than being declared here.
import type { MigrationFile } from '@bike4mind/database';
export type { MigrationFile };

// The generator writes an empty list if it ever runs against a migrations directory with no
// migration files in it. Refuse to start rather than report "nothing pending" against a real DB.
if (coreMigrations.length === 0) {
  throw new Error('core.generated.ts registers no core migrations; rerun `pnpm codegen`');
}

export const AvailableMigrations: MigrationFile[] = [...coreMigrations, ...premiumMigrations];

// Core ids are UTC timestamps stamped by `pnpm migrate generate`, never hand-picked or reused:
// scripts/check-migration-ids.mjs rejects an added id that is not a fresh generated timestamp,
// and index.test.ts checks core uniqueness on every push. There is no reason to slot an id below
// the current max - MigrationManager.up() runs every id not yet applied (see selectPending), not
// only ids above the highest applied one. Overlay ids are timestamps assigned independently in a
// private repo, so a cross-repo collision is still possible; it would silently pick whichever
// migration's id happens to sort first - fail loud instead.
const duplicateIds = [
  ...AvailableMigrations.reduce(
    (counts, m) => counts.set(m.id, (counts.get(m.id) ?? 0) + 1),
    new Map<number, number>()
  ),
]
  .filter(([, count]) => count > 1)
  .map(([id]) => id);
if (duplicateIds.length > 0) {
  throw new Error(`Duplicate migration id(s) across core + premium migrations: ${duplicateIds.join(', ')}`);
}
